# --------------------------------------------------------------------------
#  Symbole, die frueher zur Laufzeit aus ASCII-Bildern gebaut wurden (_grid).
#  Als Bild geschrieben bleiben sie lesbar und aenderbar.
# --------------------------------------------------------------------------
def _grid(rows: list[str], col: str, bg: str = "000000") -> list[str]:
    return [col if c not in "0 ." else bg for r in rows for c in r]


